DECLARE @ExpectedStock TABLE(book_id nvarchar(200) PRIMARY KEY,quantity decimal(38,10));
INSERT @ExpectedStock VALUES (N'DEMO-20261027-B01',43),(N'DEMO-20261027-B02',27),(N'DEMO-20261027-B03',18),(N'DEMO-20261027-B04',13),(N'DEMO-20261027-B05',8),(N'DEMO-20261027-B06',12),(N'DEMO-20261027-B07',24),(N'DEMO-20261027-B08',5),(N'DEMO-20261027-B09',18),(N'DEMO-20261027-B10',14),(N'DEMO-20261027-B11',0),(N'DEMO-20261027-B12',1);
IF EXISTS(SELECT 1 FROM @ExpectedStock e LEFT JOIN dbo.BookStock s ON s.book_id=e.book_id WHERE s.book_id IS NULL OR s.current_quantity<>e.quantity) THROW 51211,'Stock differs from demo baseline.',1;
IF EXISTS(SELECT 1 FROM dbo.vStockReconciliation WHERE book_id LIKE N'DEMO-20261027-%' AND difference<>0) THROW 51212,'Demo stock/ledger mismatch.',1;
IF (SELECT SUM(current_quantity) FROM dbo.BookStock WHERE book_id LIKE N'DEMO-20261027-%')<>183 THROW 51213,'Expected 183 demo units.',1;
IF (SELECT SUM(b.current_price*s.current_quantity) FROM dbo.Book b JOIN dbo.BookStock s ON s.book_id=b.book_id WHERE b.book_id LIKE N'DEMO-20261027-%')<>27555000 THROW 51214,'Catalog display value differs from baseline.',1;
IF EXISTS(SELECT 1 FROM dbo.SalesOrder o JOIN dbo.SalesOrderLine l ON l.order_id=o.order_id WHERE o.order_id LIKE N'DEMO-20261027-%' GROUP BY o.order_id,o.total_order_amount HAVING SUM(l.quantity*l.unit_price)<>o.total_order_amount) THROW 51215,'Demo order totals do not match their undiscounted lines.',1;
IF (SELECT SUM(total_order_amount) FROM dbo.SalesOrder WHERE order_id LIKE N'DEMO-20261027-%')<>1445000 THROW 51216,'Demo sale total differs.',1;
IF (SELECT SUM(refund_amount) FROM dbo.BookReturnLine WHERE return_id LIKE N'DEMO-20261027-%')<>260000 THROW 51217,'Demo refund total differs.',1;
IF EXISTS(SELECT 1 FROM dbo.BookReturnLine r JOIN dbo.BookReturn h ON h.return_id=r.return_id JOIN dbo.SalesOrderLine l ON l.order_line_id=r.original_order_line_id WHERE r.return_id LIKE N'DEMO-20261027-%' AND h.original_order_id<>l.order_id) THROW 51218,'Return references another order.',1;
IF EXISTS(SELECT r.original_order_line_id FROM dbo.BookReturnLine r JOIN dbo.SalesOrderLine l ON l.order_line_id=r.original_order_line_id WHERE r.return_id LIKE N'DEMO-20261027-%' GROUP BY r.original_order_line_id,l.quantity HAVING SUM(r.returned_quantity)>l.quantity) THROW 51219,'Return quantity exceeds purchased quantity.',1;
IF (SELECT COUNT(DISTINCT purchase_order_id) FROM dbo.vGoodsReceiptSources WHERE receipt_id=N'DEMO-20261027-GR-1')<>2 THROW 51220,'Multi-PO receipt example missing.',1;
IF (SELECT COUNT(DISTINCT receipt_id) FROM dbo.vGoodsReceiptSources WHERE purchase_order_id=N'DEMO-20261027-PO-1')<>2 THROW 51221,'Partial receiving example missing.',1;
IF (SELECT COUNT(*) FROM dbo.SalesOrderLine WHERE order_id=N'DEMO-20261027-SALE-1' AND book_id=N'DEMO-20261027-B01')<>2 THROW 51222,'Repeated Book sales-line example missing.',1;
IF (SELECT COUNT(*) FROM dbo.InventoryCountObservation WHERE count_id=N'DEMO-20261027-COUNT-HISTORY' AND book_id=N'DEMO-20261027-B01')<>2 THROW 51223,'Recount observations missing.',1;
IF (SELECT counted_quantity FROM dbo.vSelectedInventoryCount WHERE count_id=N'DEMO-20261027-COUNT-HISTORY' AND book_id=N'DEMO-20261027-B01')<>43 THROW 51224,'Selected recount must be 43, not 42+43.',1;
IF EXISTS(SELECT 1 FROM dbo.InventoryCountSelection WHERE count_id=N'DEMO-20261027-COUNT-READY') THROW 51225,'Ready Count must have observations but no selected result yet.',1;
IF EXISTS(SELECT 1 FROM dbo.CountAdjustment WHERE count_id=N'DEMO-20261027-COUNT-NOCHANGE') THROW 51226,'No-difference Count must not have an Adjustment.',1;
IF EXISTS(SELECT 1 FROM dbo.EmployeePermission WHERE employee_id=N'DEMO-20261027-EMP-SALES-B' AND permission_id=N'DEMO-20261027-UC21') THROW 51227,'Sales B is the missing-return-grant example.',1;
IF (SELECT COUNT(*) FROM dbo.EmployeePermission WHERE employee_id=N'DEMO-20261027-EMP-ADMIN')<>21 THROW 51228,'Admin fixture must contain all demo grants.',1;
IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1) THROW 51229,'A foreign key is disabled/untrusted.',1;
SELECT N'BASELINE_VERIFIED' AS demo_status,223 AS fixture_rows,12 AS books,183 AS stock_units,1445000 AS gross_order_total,260000 AS recorded_refunds;
